INSERT INTO public.clan_info (id,name,branch_subtitle,ancestral_hall,address,founding_year,motto,motto_meaning) VALUES ('main_clan','GIA PHẢ TỘC VĂN','Phả Hệ Tộc Văn (Văn Bá • Văn Tấn • Văn Phú) - Gốc tại Quảng Nam','Từ Đường Tộc Văn Bá & Nghĩa Trang Gia Tộc Gò Khoai','Làng Mỹ Xuyên Tây, nay thuộc Thị trấn Nam Phước, huyện Duy Xuyên, tỉnh Quảng Nam',1680,'ẨM THỦY TƯ NGUYÊN - VĂN KHÍ TRƯỜNG TỒN','Nhớ về cội nguồn Thanh Hóa - Mỹ Xuyên, đoàn kết các chi phái Văn Bá, Văn Tấn, Văn Phú muôn đời bền vững') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,branch_subtitle=EXCLUDED.branch_subtitle,ancestral_hall=EXCLUDED.ancestral_hall,address=EXCLUDED.address,founding_year=EXCLUDED.founding_year,motto=EXCLUDED.motto,motto_meaning=EXCLUDED.motto_meaning,updated_at=NOW();
INSERT INTO public.branches (id,name,code,leader_id,description,ancestor_id,color_accent) VALUES ('branch-vbxt','Phái II - Xuyên Tây (VBXT)','PHAI-II-VBXT','mem-506','Tộc Văn Bá – Làng cũ Mỹ Xuyên Tây, nay thuộc TT. Nam Phước, huyện Duy Xuyên, Quảng Nam. Thờ phụng Tổ tiên tại Từ Đường Tộc Văn Bá (TT. Nam Phước) và Nghĩa trang Gia tộc Gò Khoai.','mem-101','#dc2626') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,code=EXCLUDED.code,leader_id=EXCLUDED.leader_id,description=EXCLUDED.description,ancestor_id=EXCLUDED.ancestor_id,color_accent=EXCLUDED.color_accent;
INSERT INTO public.branches (id,name,code,leader_id,description,ancestor_id,color_accent) VALUES ('branch-vtqx','Phái II - Quế Xuân (VTQX)','PHAI-II-VTQX','mem-501','Chi Tộc Văn Tấn – Quế Xuân, khởi từ ngài Ngũ thế Tiên tổ Văn Tấn Vinh tại làng cũ Xuân Phú, nay thuộc xã Quế Xuân, huyện Quế Sơn, Quảng Nam. Có Nhà thờ Tộc Văn Tấn tại Quế Xuân.','mem-501','#2563eb') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,code=EXCLUDED.code,leader_id=EXCLUDED.leader_id,description=EXCLUDED.description,ancestor_id=EXCLUDED.ancestor_id,color_accent=EXCLUDED.color_accent;
INSERT INTO public.branches (id,name,code,leader_id,description,ancestor_id,color_accent) VALUES ('branch-vbdl','Phái II - Đại Lộc (VBĐL)','PHAI-II-VBĐL','mem-504','Chi Tộc Văn Bá – Đại Lộc (Chi Hà Nha), khởi từ ngài Ngũ thế Tiên tổ Văn Bá Hình tại làng cũ Hà Dục Đông, Hà Dục Tây, nay thuộc Đại Lộc, Quảng Nam. Nhà thờ Tộc tại Hà Nha, Đại Đồng.','mem-504','#d97706') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,code=EXCLUDED.code,leader_id=EXCLUDED.leader_id,description=EXCLUDED.description,ancestor_id=EXCLUDED.ancestor_id,color_accent=EXCLUDED.color_accent;
INSERT INTO public.branches (id,name,code,leader_id,description,ancestor_id,color_accent) VALUES ('branch-vpxd','Phái III - Xuyên Đông (VPXĐ)','PHAI-III-VPXĐ','mem-402','Chi Tộc Văn Phú – Xuyên Đông, khởi từ hai ngài Tuyên tổ Văn Phú Trạch và Văn Phú Súy tại làng cũ Mỹ Xuyên Đông, nay thuộc TT. Nam Phước, Duy Xuyên. Nhà thờ Chi Tộc Văn Phú tại Xuyên Đông.','mem-302','#059669') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,code=EXCLUDED.code,leader_id=EXCLUDED.leader_id,description=EXCLUDED.description,ancestor_id=EXCLUDED.ancestor_id,color_accent=EXCLUDED.color_accent;
INSERT INTO public.branches (id,name,code,leader_id,description,ancestor_id,color_accent) VALUES ('branch-vpxt','Phái IV - Xuyên Tây (VPXT)','PHAI-IV-VPXT','mem-404','Chi Tộc Văn Phú – Xuyên Tây, khởi từ ngài Tuyên tổ Văn Phú Bơi tại làng cũ Mỹ Xuyên Tây, chung Nhà thờ Tộc Văn Phú tại Mỹ Xuyên Đông.','mem-303','#7c3aed') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,code=EXCLUDED.code,leader_id=EXCLUDED.leader_id,description=EXCLUDED.description,ancestor_id=EXCLUDED.ancestor_id,color_accent=EXCLUDED.color_accent;
INSERT INTO public.branches (id,name,code,leader_id,description,ancestor_id,color_accent) VALUES ('branch-phai1','Phái I - Tiền Hiền (Trưởng Phái)','PHAI-I-VBXT','mem-101','Phái I Văn Bá - Xuyên Tây: Con trưởng và cháu đích tôn của ngài Khải tổ mất sớm, mộ táng tại Cồn Đình, năm 1976 cải táng về Nghĩa trang Gia tộc Gò Khoai.','mem-101','#b45309') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,code=EXCLUDED.code,leader_id=EXCLUDED.leader_id,description=EXCLUDED.description,ancestor_id=EXCLUDED.ancestor_id,color_accent=EXCLUDED.color_accent;
INSERT INTO public.members (id,full_name,courtesy_name,posthumous_name,gender,generation,branch_id,phai_name,chi_name,nhanh_name,order_in_family,order_title,birth_place,birth_date,birth_date_lunar,is_alive,death_date,death_date_lunar,burial_location,burial_coordinates,avatar_url,phone,email,current_address,occupation,bio,achievements,father_id,mother_id,spouse_ids,is_root_ancestor) VALUES ('mem-101','Văn Bá Bạt','1.0','Triệu Tổ Khảo Phủ Quân','male',1,NULL,NULL,NULL,NULL,1,'Nhứt thế: Triệu Tổ (1.0)','Làng Mỹ Xuyên, huyện Nông Cống, phủ Hà Trung, tỉnh Thanh Hóa (nay là xã Hà Vinh, huyện Hà Trung, Thanh Hóa)','1680-01-01','Nguyên Đán',FALSE,'1755-03-10','10/03 ÂL','Nghĩa trang Gia tộc tại Gò Khoai, xóm Mỹ Luân, TT. Nam Phước, huyện Duy Xuyên, Quảng Nam (cải táng 1976)','{"lat":15.8236,"lng":108.2392}'::jsonb,'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=150&auto=format&fit=crop&q=80',NULL,NULL,NULL,NULL,'Quê ở tỉnh Thanh Hóa, phủ Hà Trung, huyện Nông Cống, làng Mỹ Xuyên, địa diện núi Thần Phù. Nay là xã Hà Vinh, huyện Hà Trung, tỉnh Thanh Hóa. Mộ ông trước kia ở Thanh Hóa, con là ông Văn Bá Liêu sau khi lập nghiệp và ổn định ở Quảng Nam đã về quê cũ đem hài cốt cha trong một quách sành vào cải táng tại Cồn Đình, làng cũ Mỹ Xuyên Tây, nay thuộc Thị trấn Nam Phước, huyện Duy Xuyên. Năm 1976, cải táng lần 2 về nghĩa trang Gia tộc tại Gò Khoai, xóm Mỹ Luân, TT. Nam Phước.','["Ngài Triệu Tổ khai sáng cội nguồn Tộc Văn","Di dời hài cốt từ Thanh Hóa phụng táng tại Gò Khoai, Duy Xuyên, Quảng Nam","Được toàn thể 4 Phái Tộc Văn ngàn đời thờ phụng trang trọng"]'::jsonb,NULL,NULL,'[]'::jsonb,TRUE) ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name,posthumous_name=EXCLUDED.posthumous_name,generation=EXCLUDED.generation,branch_id=EXCLUDED.branch_id,phai_name=EXCLUDED.phai_name,chi_name=EXCLUDED.chi_name,nhanh_name=EXCLUDED.nhanh_name,order_in_family=EXCLUDED.order_in_family,order_title=EXCLUDED.order_title,birth_place=EXCLUDED.birth_place,birth_date=EXCLUDED.birth_date,birth_date_lunar=EXCLUDED.birth_date_lunar,is_alive=EXCLUDED.is_alive,death_date=EXCLUDED.death_date,death_date_lunar=EXCLUDED.death_date_lunar,burial_location=EXCLUDED.burial_location,burial_coordinates=EXCLUDED.burial_coordinates,avatar_url=EXCLUDED.avatar_url,phone=EXCLUDED.phone,email=EXCLUDED.email,current_address=EXCLUDED.current_address,occupation=EXCLUDED.occupation,bio=EXCLUDED.bio,achievements=EXCLUDED.achievements,father_id=EXCLUDED.father_id,mother_id=EXCLUDED.mother_id,spouse_ids=EXCLUDED.spouse_ids,is_root_ancestor=EXCLUDED.is_root_ancestor,updated_at=NOW();
INSERT INTO public.members (id,full_name,courtesy_name,posthumous_name,gender,generation,branch_id,phai_name,chi_name,nhanh_name,order_in_family,order_title,birth_place,birth_date,birth_date_lunar,is_alive,death_date,death_date_lunar,burial_location,burial_coordinates,avatar_url,phone,email,current_address,occupation,bio,achievements,father_id,mother_id,spouse_ids,is_root_ancestor) VALUES ('mem-201','Văn Bá Liêu','Sử - Trình - Lư (2.0)','Khải Tổ Phủ Quân','male',2,NULL,NULL,NULL,NULL,1,'Nhị thế: Khải Tổ (2.0)','Mỹ Xuyên Tây, TT. Nam Phước, Duy Xuyên, Quảng Nam','1710-04-15','15/03 ÂL',FALSE,'1785-08-12','08/07 ÂL','Nghĩa trang Gia tộc tại Gò Khoai, Xuyên Tây (cải táng 1976 từ Cồn Đình)','{"lat":15.8238,"lng":108.2395}'::jsonb,'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&auto=format&fit=crop&q=80',NULL,NULL,NULL,NULL,'Con ông Văn Bá Bạt. Tên ông thường gọi là: Sử - Trình - Lư. Khởi đầu lập nghiệp vững vàng tại làng cũ Mỹ Xuyên Tây, Duy Xuyên, Quảng Nam. Ngài đã thân hành về lại quê cũ Thanh Hóa mang quách sành đựng hài cốt thân phụ vào an táng tại Cồn Đình, mở rộng cơ nghiệp, lập Từ Đường Tộc Văn Bá tại Mỹ Xuyên Tây.','["Khai cơ lập nghiệp tại làng Mỹ Xuyên Tây, Duy Xuyên","Nghinh hài cốt Triệu Tổ từ Thanh Hóa vào Quảng Nam","Khởi sinh 4 Phái Tộc Văn lẫy lừng","Dựng Từ đường Tộc Văn Bá tại Thị trấn Nam Phước"]'::jsonb,'mem-101',NULL,'["mem-201-w1","mem-201-w2"]'::jsonb,FALSE) ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name,posthumous_name=EXCLUDED.posthumous_name,generation=EXCLUDED.generation,branch_id=EXCLUDED.branch_id,phai_name=EXCLUDED.phai_name,chi_name=EXCLUDED.chi_name,nhanh_name=EXCLUDED.nhanh_name,order_in_family=EXCLUDED.order_in_family,order_title=EXCLUDED.order_title,birth_place=EXCLUDED.birth_place,birth_date=EXCLUDED.birth_date,birth_date_lunar=EXCLUDED.birth_date_lunar,is_alive=EXCLUDED.is_alive,death_date=EXCLUDED.death_date,death_date_lunar=EXCLUDED.death_date_lunar,burial_location=EXCLUDED.burial_location,burial_coordinates=EXCLUDED.burial_coordinates,avatar_url=EXCLUDED.avatar_url,phone=EXCLUDED.phone,email=EXCLUDED.email,current_address=EXCLUDED.current_address,occupation=EXCLUDED.occupation,bio=EXCLUDED.bio,achievements=EXCLUDED.achievements,father_id=EXCLUDED.father_id,mother_id=EXCLUDED.mother_id,spouse_ids=EXCLUDED.spouse_ids,is_root_ancestor=EXCLUDED.is_root_ancestor,updated_at=NOW();
INSERT INTO public.members (id,full_name,courtesy_name,posthumous_name,gender,generation,branch_id,phai_name,chi_name,nhanh_name,order_in_family,order_title,birth_place,birth_date,birth_date_lunar,is_alive,death_date,death_date_lunar,burial_location,burial_coordinates,avatar_url,phone,email,current_address,occupation,bio,achievements,father_id,mother_id,spouse_ids,is_root_ancestor) VALUES ('mem-201-w1','Huỳnh Thị Bạch',NULL,NULL,'female',2,NULL,NULL,NULL,NULL,1,'Vợ Chánh (Chánh Thất Khải Tổ Tỷ)',NULL,NULL,NULL,FALSE,NULL,NULL,'Nghĩa trang Gia tộc tại Gò Khoai, Xuyên Tây (cải táng 1976 từ Cồn Đô)',NULL,NULL,NULL,NULL,NULL,NULL,'Vợ chánh của ngài Nhị thế Khải tổ Văn Bá Liêu. Mộ trước táng tại Cồn Đô, làng cũ Mỹ Xuyên Tây, nay thuộc Thị trấn Nam Phước. Năm 1976 cải táng về nghĩa trang Gia tộc tại Gò Khoai, Xuyên Tây. Sanh hạ: Con trưởng [Trưởng Nam] (Phái I), Văn Bá Lục (Phái II), Văn Bá Nghi (Phái III).','[]'::jsonb,NULL,NULL,'["mem-201"]'::jsonb,FALSE) ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name,posthumous_name=EXCLUDED.posthumous_name,generation=EXCLUDED.generation,branch_id=EXCLUDED.branch_id,phai_name=EXCLUDED.phai_name,chi_name=EXCLUDED.chi_name,nhanh_name=EXCLUDED.nhanh_name,order_in_family=EXCLUDED.order_in_family,order_title=EXCLUDED.order_title,birth_place=EXCLUDED.birth_place,birth_date=EXCLUDED.birth_date,birth_date_lunar=EXCLUDED.birth_date_lunar,is_alive=EXCLUDED.is_alive,death_date=EXCLUDED.death_date,death_date_lunar=EXCLUDED.death_date_lunar,burial_location=EXCLUDED.burial_location,burial_coordinates=EXCLUDED.burial_coordinates,avatar_url=EXCLUDED.avatar_url,phone=EXCLUDED.phone,email=EXCLUDED.email,current_address=EXCLUDED.current_address,occupation=EXCLUDED.occupation,bio=EXCLUDED.bio,achievements=EXCLUDED.achievements,father_id=EXCLUDED.father_id,mother_id=EXCLUDED.mother_id,spouse_ids=EXCLUDED.spouse_ids,is_root_ancestor=EXCLUDED.is_root_ancestor,updated_at=NOW();
