INSERT INTO public.members (id,full_name,courtesy_name,posthumous_name,gender,generation,branch_id,phai_name,chi_name,nhanh_name,order_in_family,order_title,birth_place,birth_date,birth_date_lunar,is_alive,death_date,death_date_lunar,burial_location,burial_coordinates,avatar_url,phone,email,current_address,occupation,bio,achievements,father_id,mother_id,spouse_ids,is_root_ancestor) VALUES ('mem-301','Văn Bá Lục','Châu Ký (II.3.002)','Thỉ Tổ Phái II Phủ Quân','male',3,'branch-vbxt','Phái II-VBXT','Chi 1 & Chi 2','Xuyên Tây',2,'Tam thế: Thỉ Tổ (Phái II-VBXT)','Mỹ Xuyên Tây, Duy Xuyên, Quảng Nam',NULL,NULL,FALSE,NULL,NULL,'Nghĩa trang Gia tộc tại Gò Khoai, Xuyên Tây (cải táng 1976 từ xứ Tân Kiều)',NULL,'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=150&auto=format&fit=crop&q=80',NULL,NULL,NULL,NULL,'Thường gọi là Châu Ký. Con thứ hai của ngài Văn Bá Liêu, cháu nội ngài Triệu tổ Văn Bá Bạt. Ngài khởi phát Phái II Tộc Văn Bá – Xuyên Tây. Mộ trước táng tại xứ Tân Kiều, làng cũ Mỹ Xuyên Tây, năm 1976 cải táng về nghĩa trang Gia tộc tại Gò Khoai, Xuyên Tây. Sanh hạ: Văn Quang Đạo (Phụng) và Văn Tấn Thành.','["Khởi lập Phái II Tộc Văn Bá - Xuyên Tây"]'::jsonb,'mem-201','mem-201-w1','["mem-301-w"]'::jsonb,FALSE) ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name,posthumous_name=EXCLUDED.posthumous_name,generation=EXCLUDED.generation,branch_id=EXCLUDED.branch_id,phai_name=EXCLUDED.phai_name,chi_name=EXCLUDED.chi_name,nhanh_name=EXCLUDED.nhanh_name,order_in_family=EXCLUDED.order_in_family,order_title=EXCLUDED.order_title,birth_place=EXCLUDED.birth_place,birth_date=EXCLUDED.birth_date,birth_date_lunar=EXCLUDED.birth_date_lunar,is_alive=EXCLUDED.is_alive,death_date=EXCLUDED.death_date,death_date_lunar=EXCLUDED.death_date_lunar,burial_location=EXCLUDED.burial_location,burial_coordinates=EXCLUDED.burial_coordinates,avatar_url=EXCLUDED.avatar_url,phone=EXCLUDED.phone,email=EXCLUDED.email,current_address=EXCLUDED.current_address,occupation=EXCLUDED.occupation,bio=EXCLUDED.bio,achievements=EXCLUDED.achievements,father_id=EXCLUDED.father_id,mother_id=EXCLUDED.mother_id,spouse_ids=EXCLUDED.spouse_ids,is_root_ancestor=EXCLUDED.is_root_ancestor,updated_at=NOW();
