INSERT INTO public.members (id,full_name,courtesy_name,posthumous_name,gender,generation,branch_id,phai_name,chi_name,nhanh_name,order_in_family,order_title,birth_place,birth_date,birth_date_lunar,is_alive,death_date,death_date_lunar,burial_location,burial_coordinates,avatar_url,phone,email,current_address,occupation,bio,achievements,father_id,mother_id,spouse_ids,is_root_ancestor) VALUES ('mem-302','Văn Bá Nghi','III.3.003','Thỉ Tổ Phái III Phủ Quân','male',3,'branch-vpxd','Phái III-VBXT','Xuyên Đông','Khởi Tộc Văn Phú',3,'Tam thế: Thỉ Tổ (Phái III-VBXT)','Mỹ Xuyên Tây, Duy Xuyên, Quảng Nam',NULL,NULL,FALSE,NULL,NULL,'Nghĩa trang Gia tộc tại Gò Khoai, Xuyên Tây (cải táng 1976 từ Cồn Đình)',NULL,NULL,NULL,NULL,NULL,NULL,'Con thứ ba của ngài Văn Bá Liêu, cháu nội ngài Văn Bá Bạt. Khởi đầu Phái Ba. Mộ táng tại Cồn Đình, năm 1976 cải táng về nghĩa trang Gia tộc Gò Khoai. Sanh hạ hai ngài Văn Phú Trạch và Văn Phú Súy, bắt đầu tách từ Tộc Văn Bá – Xuyên Tây thành Chi tộc riêng: Tộc Văn Phú tại làng cũ Mỹ Xuyên Đông, lập Nhà thờ Tộc Văn Phú tại Xuyên Đông.','["Khởi tổ Phái III, tiền đề thành lập Tộc Văn Phú - Xuyên Đông"]'::jsonb,'mem-201','mem-201-w1','["mem-302-w"]'::jsonb,FALSE) ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name,posthumous_name=EXCLUDED.posthumous_name,generation=EXCLUDED.generation,branch_id=EXCLUDED.branch_id,phai_name=EXCLUDED.phai_name,chi_name=EXCLUDED.chi_name,nhanh_name=EXCLUDED.nhanh_name,order_in_family=EXCLUDED.order_in_family,order_title=EXCLUDED.order_title,birth_place=EXCLUDED.birth_place,birth_date=EXCLUDED.birth_date,birth_date_lunar=EXCLUDED.birth_date_lunar,is_alive=EXCLUDED.is_alive,death_date=EXCLUDED.death_date,death_date_lunar=EXCLUDED.death_date_lunar,burial_location=EXCLUDED.burial_location,burial_coordinates=EXCLUDED.burial_coordinates,avatar_url=EXCLUDED.avatar_url,phone=EXCLUDED.phone,email=EXCLUDED.email,current_address=EXCLUDED.current_address,occupation=EXCLUDED.occupation,bio=EXCLUDED.bio,achievements=EXCLUDED.ach