INSERT INTO public.members (id,full_name,courtesy_name,posthumous_name,gender,generation,branch_id,phai_name,chi_name,nhanh_name,order_in_family,order_title,birth_place,birth_date,birth_date_lunar,is_alive,death_date,death_date_lunar,burial_location,burial_coordinates,avatar_url,phone,email,current_address,occupation,bio,achievements,father_id,mother_id,spouse_ids,is_root_ancestor) VALUES ('mem-401','Văn Tấn Thành','Chỉnh Trai (II.4.001)','Tuyên Tổ Phủ Quân','male',4,'branch-vbxt','Phái II-VBXT','Chi 1 & Chi 2','Xuyên Tây',2,'Tứ thế: Tuyên Tổ (II.4.001)','Mỹ Xuyên Tây, Duy Xuyên, Quảng Nam',NULL,NULL,FALSE,NULL,NULL,'Nghĩa trang Gia tộc tại Gò Khoai, Xuyên Tây (cải táng 1976 từ Cồn Đình)',NULL,'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&auto=format&fit=crop&q=80',NULL,NULL,NULL,NULL,'Thường gọi là Chỉnh Trai. Con ông Văn Bá Lục, cháu nội ông Văn Bá Liêu. Mộ ông bà song táng tại Cồn Đình, năm 1976 cải táng về nghĩa trang Gia tộc tại Gò Khoai. Sanh hạ 6 người con trai mở ra các chi nhánh lớn của Phái II: Văn Tấn Vinh (bắt đầu Phái II Tộc Văn Tấn - Quế Xuân), Văn Tấn Ba (Gia Định), Văn Bá Liễu, Văn Bá Hình (bắt đầu Phái II Tộc Văn Bá - Đại Lộc), Văn Bá Lý, Văn Bá Đình (kế tục Phái II Tộc Văn Bá - Xuyên Tây).','["Tuyên tổ sinh 6 người con trai mở rộng địa bàn Tộc Văn khắp Quảng Nam và Nam Bộ"]'::jsonb,'mem-301','mem-301-w','["mem-401-w"]'::jsonb,FALSE) ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name,posthumous_name=EXCLUDED.posthumous_name,generation=EXCLUDED.generation,branch_id=EXCLUDED.branch_id,phai_name=EXCLUDED.phai_name,chi_name=EXCLUDED.chi_name,nhanh_name=EXCLUDED.nhanh_name,order_in_family=EXCLUDED.order_in_family,order_title=EXCLUDED.order_title,birth_place=EXCLUDED.birth_place,birth_date=EXCLUDED.birth_date,birth_date_lunar=EXCLUDED.birth_date_lunar,is_alive=EXCLUDED.is_alive,death_date=EXCLUDED.death_date,death_date_lunar=EXCLUDED.death_date_lunar,burial_location=EXCLUDED.burial_location,burial_coordinates=EXCLUDED.burial