INSERT INTO public.members (id,full_name,courtesy_name,posthumous_name,gender,generation,branch_id,phai_name,chi_name,nhanh_name,order_in_family,order_title,birth_place,birth_date,birth_date_lunar,is_alive,death_date,death_date_lunar,burial_location,burial_coordinates,avatar_url,phone,email,current_address,occupation,bio,achievements,father_id,mother_id,spouse_ids,is_root_ancestor) VALUES ('mem-506','Văn Bá Đình','Tiểu Triều (II.5.006)','Tiên Tổ Phủ Quân','male',5,'branch-vbxt','Phái II-VBXT','Chi 1 & Chi 2','Kế tục Xuyên Tây',6,'Ngũ thế: Tiên Tổ (II.5.006)','Mỹ Xuyên Tây, Duy Xuyên, Quảng Nam',NULL,NULL,FALSE,NULL,NULL,'Nghĩa trang Gia tộc tại Gò Khoai, Xuyên Tây (cải táng 1976 từ xứ Bàu Sen)',NULL,'https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?w=150&auto=format&fit=crop&q=80',NULL,NULL,NULL,NULL,'Thường gọi là Tiểu Triều. Con ông Văn Tấn Thành, cháu nội ông Văn Bá Lục. Ngài kế tục gia phả Tộc Văn Bá – Xuyên Tây và thờ phụng Tổ tiên từ ngài Triệu tổ xuống tại Nhà thờ Tộc Văn Bá TT. Nam Phước. Mộ trước táng tại Bàu Sen, năm 1976 cải táng về nghĩa trang Gia tộc tại Gò Khoai. Vợ là bà Trần Thị Hút (hiệu Thôn Khí, mất ngày 15/3 ÂL). Sanh hạ 5 con trai: Văn Bá Đồng, Văn Bá Trung (bắt đầu Chi 1), Văn Bá Trinh (mộ táng Gia Định), Văn Bá Trang, Văn Bá Đài (bắt đầu Chi 2).','["Kế tục Tộc Văn Bá - Xuyên Tây, sinh dưỡng hai vị tổ Chi 1 và Chi 2"]'::jsonb,'mem-401','mem-401-w','["mem-506-w"]'::jsonb,FALSE) ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name,posthumous_name=EXCLUDED.posthumous_name,generation=EXCLUDED.generation,branch_id=EXCLUDED.branch_id,phai_name=EXCLUDED.phai_name,chi_name=EXCLUDED.chi_name,nhanh_name=EXCLUDED.nhanh_name,order_in_family=EXCLUDED.order_in_family,order_title=EXCLUDED.order_title,birth_place=EXCLUDED.birth_place,birth_date=EXCLUDED.birth_date,birth_date_lunar=EXCLUDED.birth_date_lunar,is_alive=EXCLUDED.is_alive,death_date=EXCLUDED.death_date,death_date_lunar=EXCLUDED.death_date_lunar,burial_location=EXCLUDED.burial_location,burial_coordinates=EXCLUDED.burial_coordinates,avatar_url=EXCLUDED.avatar_url,phone=EXCLUDED.phone,email=EXCLUDED.email,current_address=EXCLUDED.current_address,occupation=EXCLUDED.occupation,bio=EXCLUDED.bio,achievements=EXCLUDED.achievements,father_id=EXCLUDED.father_id,mother_id=EXCLUDED.mother_id,spouse_ids=EXCLUDED.spouse_ids,is_root_ancestor=EXCLUDED.is_root_ancestor,updated_at=NOW();
