INSERT INTO public.documents (id,title,category,category_label,file_url,file_type,description,recorded_date,dynasty_era,author_or_preserver,tags,images) VALUES ('doc-1','Bản thảo Gia Phả Tộc Văn (Cập nhật 20/7/2023)','pha_ky','Phả hệ toàn tộc','https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?w=800&auto=format&fit=crop&q=80','pdf','Bộ gia phả đồ sộ ghi chép từ Đời thứ 1 (ngài Triệu Tổ Văn Bá Bạt) đến Đời thứ 14, bao gồm các Phái: Văn Bá Xuyên Tây, Văn Tấn Quế Xuân, Văn Bá Đại Lộc, Văn Phú Xuyên Đông và Xuyên Tây.','2023-07-20','Hiện đại - Cập nhật 2023','Hội đồng Gia tộc Tộc Văn biên soạn','["Gia phả toàn tộc","Văn Bá","Văn Tấn","Văn Phú"]'::jsonb,'[{"id":"img-1-1","url":"https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?w=800&auto=format&fit=crop&q=80","caption":"Bìa cuốn Đại phả hệ Tộc Văn - Công trình sưu khảo và biên tập công phu qua nhiều thế hệ con cháu bốn Phái."},{"id":"img-1-2","url":"https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80","caption":"Trang mở đầu ghi chép công đức ngài Triệu Tổ Văn Bá Bạt cùng sắc chỉ khai canh khai khẩn vùng đất Mỹ Xuyên Tây."},{"id":"img-1-3","url":"https://images.unsplash.com/photo-1544717305-2782549b5136?w=800&auto=format&fit=crop&q=80","caption":"Sơ đồ cây phả hệ phân bổ 4 Phái lớn: Văn Bá Xuyên Tây, Văn Tấn Quế Xuân, Văn Bá Đại Lộc và Văn Phú."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,category=EXCLUDED.category,category_label=EXCLUDED.category_label,file_url=EXCLUDED.file_url,file_type=EXCLUDED.file_type,description=EXCLUDED.description,recorded_date=EXCLUDED.recorded_date,dynasty_era=EXCLUDED.dynasty_era,author_or_preserver=EXCLUDED.author_or_preserver,tags=EXCLUDED.tags,images=EXCLUDED.images;
INSERT INTO public.documents (id,title,category,category_label,file_url,file_type,description,recorded_date,dynasty_era,author_or_preserver,tags,images) VALUES ('doc-2','Gia Phả Tộc Văn Lập Ngày 28/3/1960 (Bộ 4 Bản Gốc)','pha_ky','Gia phả cổ truyền 1960','https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80','pdf','Gia phả Tộc Văn lập ngày 28/3/1960 chia thành 04 bản: 01 bản Phái Nhì Chi Nhất (Quế Sơn giữ), 01 bản Phái Nhì Chi Nhì (Xuyên Tây giữ), 01 bản Phái Ba (Xuyên Đông giữ), 01 bản Phái Tư (Xuyên Tây giữ). Tất cả các Phái đều phụng nghinh về thờ phụng.','1960-03-28','Năm Canh Tý 1960','Cháu đời 11 & 12 bốn Phái đồng phụng sao','["Gia phả 1960","Tư liệu quý","4 Bản gốc"]'::jsonb,'[{"id":"img-2-1","url":"https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80","caption":"Bản sao gia phả Canh Tý 1960 bằng mực tàu trên giấy dó cổ, do các vị trưởng lão đời 11 và 12 đồng thủ bút."},{"id":"img-2-2","url":"https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?w=800&auto=format&fit=crop&q=80","caption":"Dấu ấn kiềm và chữ ký của đại diện 4 Phái tại lễ cung nghinh gia phả về Từ Đường Tộc Văn Bá."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,category=EXCLUDED.category,category_label=EXCLUDED.category_label,file_url=EXCLUDED.file_url,file_type=EXCLUDED.file_type,description=EXCLUDED.description,recorded_date=EXCLUDED.recorded_date,dynasty_era=EXCLUDED.dynasty_era,author_or_preserver=EXCLUDED.author_or_preserver,tags=EXCLUDED.tags,images=EXCLUDED.images;
INSERT INTO public.documents (id,title,category,category_label,file_url,file_type,description,recorded_date,dynasty_era,author_or_preserver,tags,images) VALUES ('doc-3','Bản Dập Văn Bia Mộ Ngài Triệu Tổ Văn Bá Bạt tại Gò Khoai (1976)','sac_phong','Văn bia mộ tổ','https://images.unsplash.com/photo-1544717305-2782549b5136?w=800&auto=format&fit=crop&q=80','image','Bản dập và ảnh chụp toàn văn bia đá khắc năm 1976 khi di dời mộ ngài Triệu Tổ và các tiền hiền về Nghĩa trang Gia tộc tại Gò Khoai, Xuyên Tây.','1976-11-15','Năm Bính Thìn 1976','Hội đồng Trưởng tộc Văn Bá','["Bia mộ","Triệu Tổ","Gò Khoai"]'::jsonb,'[{"id":"img-3-1","url":"https://images.unsplash.com/photo-1544717305-2782549b5136?w=800&auto=format&fit=crop&q=80","caption":"Bản dập rập mực thác bản văn bia bằng đá Thanh, khắc chữ Hán chân phương ghi rõ hành trạng ngài Triệu Tổ."},{"id":"img-3-2","url":"https://images.unsplash.com/photo-1507842229451-79b1be886a27?w=800&auto=format&fit=crop&q=80","caption":"Quang cảnh khu lăng mộ ngài Triệu Tổ Văn Bá Bạt tại vị trí trung tâm Nghĩa trang Gia tộc Gò Khoai."},{"id":"img-3-3","url":"https://images.unsplash.com/photo-1513542789411-b6a5d4f31634?w=800&auto=format&fit=crop&q=80","caption":"Văn tế cổ và bản dịch quốc ngữ khắc trên bia phụ kế bên nhằm lưu truyền cho hậu bối."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,category=EXCLUDED.category,category_label=EXCLUDED.category_label,file_url=EXCLUDED.file_url,file_type=EXCLUDED.file_type,description=EXCLUDED.description,recorded_date=EXCLUDED.recorded_date,dynasty_era=EXCLUDED.dynasty_era,author_or_preserver=EXCLUDED.author_or_preserver,tags=EXCLUDED.tags,images=EXCLUDED.images;
INSERT INTO public.documents (id,title,category,category_label,file_url,file_type,description,recorded_date,dynasty_era,author_or_preserver,tags,images) VALUES ('doc-4','Mỹ Xuyên Tây: Lịch Sử, Địa Lý và Văn Hóa (Xuất bản T3-2020)','huong_uoc','Địa chí & Lịch sử dòng tộc','https://images.unsplash.com/photo-1507842229451-79b1be886a27?w=800&auto=format&fit=crop&q=80','doc','Tài liệu nghiên cứu lịch sử lập làng Mỹ Xuyên Tây, hành trình đưa hài cốt Triệu Tổ từ Thanh Hóa vào Quảng Nam, và lịch sử Nghĩa trang Gò Khoai xưa và nay.','2020-03-01','Xuất bản Tháng 3/2020','Ban Liên Lạc & Nghiên cứu Lịch sử Văn Tộc','["Địa chí","Mỹ Xuyên Tây","Lịch sử"]'::jsonb,'[{"id":"img-4-1","url":"https://images.unsplash.com/photo-1507842229451-79b1be886a27?w=800&auto=format&fit=crop&q=80","caption":"Bản đồ cổ địa giới làng Mỹ Xuyên Tây và các cồn bãi nơi tổ tiên khai phá ven sông Thu Bồn."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,category=EXCLUDED.category,category_label=EXCLUDED.category_label,file_url=EXCLUDED.file_url,file_type=EXCLUDED.file_type,description=EXCLUDED.description,recorded_date=EXCLUDED.recorded_date,dynasty_era=EXCLUDED.dynasty_era,author_or_preserver=EXCLUDED.author_or_preserver,tags=EXCLUDED.tags,images=EXCLUDED.images;
