INSERT INTO public.posts (id,title,author_name,author_role,avatar_url,created_at,category,content,images,likes_count,comments_count) VALUES ('post-1','Thông báo Lễ Tảo Mộ Tiết Thanh Minh 2026 tại Nghĩa Trang Gia Tộc Gò Khoai','Ban Khánh Tiết Tộc Văn Bá','Trưởng Ban Khánh Tiết','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&auto=format&fit=crop&q=80','05/09/2026','thong_bao','Kính gửi toàn thể con cháu nội ngoại bốn Phái (Văn Bá, Văn Tấn, Văn Phú). Đúng tiết Thanh Minh năm nay, Hội đồng gia tộc tổ chức dọn cỏ, chỉnh trang khuôn viên bia mộ ngài Triệu Tổ và các cụ Tiên tổ tại Nghĩa trang Gò Khoai, TT. Nam Phước. Kính mời bà con bố trí tề tựu đông đủ.','[]'::jsonb,68,24) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,author_name=EXCLUDED.author_name,author_role=EXCLUDED.author_role,avatar_url=EXCLUDED.avatar_url,category=EXCLUDED.category,content=EXCLUDED.content,images=EXCLUDED.images,likes_count=EXCLUDED.likes_count,comments_count=EXCLUDED.comments_count;
INSERT INTO public.posts (id,title,author_name,author_role,avatar_url,created_at,category,content,images,likes_count,comments_count) VALUES ('post-2','Vinh danh con cháu Tộc Văn đạt thành tích xuất sắc và nhận Quỹ Khuyến học năm 2026','Hội Đồng Khuyến Học Tộc Văn','Ban Khuyến Học','https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&auto=format&fit=crop&q=80','28/08/2026','khuyen_hoc','Thay mặt Hội đồng Tộc Văn, xin chúc mừng các cháu thuộc Phái II-VBXT, Phái II-VTQX, Phái II-VBĐL, Phái III-VPXĐ và Phái IV-VPXT đã đỗ đạt đại học và đạt học sinh giỏi năm học vừa qua. Buổi trao học bổng sẽ diễn ra trang trọng tại Từ đường Tộc Văn Bá.','[]'::jsonb,55,18) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,author_name=EXCLUDED.author_name,author_role=EXCLUDED.author_role,avatar_url=EXCLUDED.avatar_url,category=EXCLUDED.category,content=EXCLUDED.content,images=EXCLUDED.images,likes_count=EXCLUDED.likes_count,comments_count=EXCLUDED.comments_count;
